    /**
     * Get a random country
     */
    public static function getRandomCountry(): string {
        return self::COUNTRIES[array_rand(self::COUNTRIES)];
    }

    /**
     * Get a random words concatenated in a single string
     */
    public static function getRandomWords(int $count): string {
        $words = array_values(self::RANDOM_WORDS);
        if (empty($words)) {
            return '';
        }

        $result = [];

        for ($i = 0; $i < $count; $i++) {
            $result[] = $words[array_rand($words)];
        }

        return implode('  ', $result);
    }

    /**
     * Get all names (male + female combined)
     */
    public static function getAllNames(): array {
        return array_merge(self::MALE_NAMES, self::FEMALE_NAMES);
    }

    /**
     * Get a random male name
     */
    public static function getRandomMaleName(): string {
        return self::MALE_NAMES[array_rand(self::MALE_NAMES)];
    }

    /**
     * Get a random female name
     */
    public static function getRandomFemaleName(): string {
        return self::FEMALE_NAMES[array_rand(self::FEMALE_NAMES)];
    }

    /**
     * Get a random name (any gender)
     */
    public static function getRandomName(): string {
        $allNames = self::getAllNames();
        return $allNames[array_rand($allNames)];
    }

    /**
     * Get a random surname
     */
    public static function getRandomSurname(): string {
        return self::SURNAMES[array_rand(self::SURNAMES)];
    }

    /**
     * Get a random Ethiopian region
     */
    public static function getRandomRegion(): string {
        return self::REGIONS[array_rand(self::REGIONS)];
    }

    /**
     * Get a random Ethiopian city
     */
    public static function getRandomCity(): string {
        return self::CITIES[array_rand(self::CITIES)];
    }

    /**
     * Get a random phone prefix
     */
    public static function getRandomPhonePrefix(): string {
        return self::PHONE_PREFIXES[array_rand(self::PHONE_PREFIXES)];
    }

    /**
     * Get a random Inclusiveness
     */
    public static function getRandomInclusiveness(): string {
        return self::RANDOM_INCLUSIVENESS[array_rand(self::RANDOM_INCLUSIVENESS)];
    }
